sp_css.css:
body { background: $body-bg; font-family: $font-family-base; }
/* Card look used by every TrackMed widget */
.tm-card {
background: $card-bg; border-radius: $border-radius-base;
box-shadow: 0 1px 4px rgba(16,32,70,.08);
padding: 16px 20px; margin-bottom: 16px;
}
/* Status pills (matches mock-up) */
.tm-pill { border-radius: 999px; padding: 2px 12px; font-size: 12px; font-weight: 600; }
.tm-pill.active, .tm-pill.taken, .tm-pill.completed { background:#E7F7EE; color:$success; }
.tm-pill.pending, .tm-pill.medium { background:#FFF4E0; color:$warning; }
.tm-pill.missed, .tm-pill.high, .tm-pill.inactive,
.tm-pill.rejected { background:#FDE8E8; color:$danger; }
.tm-pill.approved { background:#E7F7EE; color:$success; }
/* Primary buttons */
.btn-primary { background:$brand-primary; border-color:$brand-primary; border-radius:8px; }
